<?php
session_start(); include('check-login.php'); include('dbstring.php'); include_once('result-access-utils.php');
if(!isset($_SESSION['ACCESSLEVEL']) || $_SESSION['ACCESSLEVEL']!=='administrator'){ http_response_code(403); exit('Administrator access required.'); }
result_access_ensure_tables($con); $msg='';
if(empty($_SESSION['result_access_csrf'])) { $_SESSION['result_access_csrf']=bin2hex(random_bytes(32)); }
if(isset($_POST['save_rule'])){
 $b=trim((string)(isset($_POST['batchid'])?$_POST['batchid']:'')); $y=trim((string)(isset($_POST['academicyear'])?$_POST['academicyear']:'')); $t=(int)(isset($_POST['termname'])?$_POST['termname']:0); $c=trim((string)(isset($_POST['classid'])?$_POST['classid']:''));
 $mode=in_array($_POST['mode'],array('free','closed','payment'),true)?$_POST['mode']:'free'; $amount=max(0,(float)$_POST['amount']); $enabled=isset($_POST['enabled'])?1:0;
 if(!hash_equals($_SESSION['result_access_csrf'],isset($_POST['csrf'])?$_POST['csrf']:'')) { $msg='Your session expired. Please refresh and try again.'; }
 elseif($b===''||$y===''||$t<1||$c==='') { $msg='Choose class, batch, year and semester.'; }
 else {
   $id=result_access_id('RAC_'); $be=mysqli_real_escape_string($con,$b); $ye=mysqli_real_escape_string($con,$y); $ce=mysqli_real_escape_string($con,$c); $me=mysqli_real_escape_string($con,$mode);
   $note=isset($_POST['note'])?$_POST['note']:''; $ne=mysqli_real_escape_string($con,trim((string)$note)); $user=isset($_SESSION['USERID'])?$_SESSION['USERID']:''; $ue=mysqli_real_escape_string($con,(string)$user);
   $sql="INSERT INTO tblresultaccesssetting(settingid,batchid,academicyear,termname,classid,mode,amount,currency,note,enabled,updatedby,updatedat) VALUES('$id','$be','$ye',$t,'$ce','$me',$amount,'GHS','$ne',$enabled,'$ue',NOW()) ON DUPLICATE KEY UPDATE mode='$me',amount=$amount,note='$ne',enabled=$enabled,updatedby='$ue',updatedat=NOW()";
   $msg=mysqli_query($con,$sql)?'Result access rule saved.':'The rule could not be saved. Please try again.';
 }
}
$batches=mysqli_query($con,"SELECT batchid,batch FROM tblbatch ORDER BY datetimeentry DESC");$classes=mysqli_query($con,"SELECT class_entryid,class_name FROM tblclassentry ORDER BY class_name");
$homePage=(isset($_SESSION['SYSTEMTYPE']) && $_SESSION['SYSTEMTYPE']==='super_user') ? 'super.php' : 'admin.php';
?>
<!doctype html><html><head><?php include('links.php');?><title>Result Access Control</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.box{max-width:900px;margin:35px auto;background:#fff;padding:28px;border-radius:18px;box-shadow:0 8px 25px #dce6ee}.page-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.home-link{display:inline-block;background:#e7eef5;color:#17314b!important;text-decoration:none;padding:11px 14px;border-radius:9px;font-weight:bold;white-space:nowrap}label{display:block;font-weight:bold;margin-top:14px}.box input:not([type=checkbox]),.box select,.box textarea{width:100%!important;padding:11px!important;margin-top:5px;box-sizing:border-box;background:#fff!important;color:#102a43!important;border:1px solid #9db2c5!important;border-radius:8px;font:16px Arial,sans-serif!important;opacity:1!important}.box select{height:46px!important}.box select option{background:#fff!important;color:#102a43!important}.box input[type=checkbox]{width:18px!important;height:18px!important;vertical-align:middle;accent-color:#087443}.box textarea{min-height:90px}.box button{margin-top:20px;background:#087443;color:white;border:0;border-radius:10px;padding:13px 18px;font-weight:bold}.note{padding:12px;background:#ecfdf3;color:#075a35;border-radius:10px}@media(max-width:560px){.page-head{display:block}.home-link{margin-top:8px}}</style></head><body><main class="box"><div class="page-head"><div><h1>Manage Result Access</h1><p>Choose whether students can view a class result for a particular semester. Leave a rule disabled to keep results available as normal.</p></div><a class="home-link" href="<?php echo htmlspecialchars($homePage); ?>"><i class="fa fa-home"></i> Admin Home</a></div><?php if($msg!=='')echo '<p class="note">'.htmlspecialchars($msg).'</p>';?><form method="post"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['result_access_csrf']);?>"><label>Student batch</label><select name="batchid" required><option value="">Choose a batch</option><?php while($r=mysqli_fetch_assoc($batches))echo '<option value="'.htmlspecialchars($r['batchid']).'">'.htmlspecialchars($r['batch']).'</option>';?></select><label>Academic year</label><input name="academicyear" value="<?php echo date('Y');?>" required><label>Semester</label><select name="termname"><option value="1">Semester 1</option><option value="2">Semester 2</option><option value="3">Semester 3</option></select><label>Class</label><select name="classid" required><option value="">Choose a class</option><?php while($r=mysqli_fetch_assoc($classes))echo '<option value="'.htmlspecialchars($r['class_entryid']).'">'.htmlspecialchars($r['class_name']).'</option>';?></select><label>How should students access this result?</label><select name="mode"><option value="free">Allow all students to view it for free</option><option value="closed">Do not allow students to view it yet</option><option value="payment">Require payment before viewing</option></select><label>Result viewing fee (GHS)</label><input type="number" min="0" step="0.01" name="amount" value="0"><label>Message shown to students (optional)</label><textarea name="note" placeholder="Example: Please complete the result viewing payment to continue."></textarea><label><input type="checkbox" name="enabled" value="1"> Apply this setting to the selected result</label><button name="save_rule">Save Result Access Setting</button></form></main></body></html>
